INSERT INTO trucker.customer_pg
  (id, customer_id, current_cdemo_sk, current_hdemo_sk, current_addr_sk,
   first_shipto_date_sk, first_sales_date_sk, salutation, first_name, last_name,
   preferred_cust_flag, birth_day, birth_month, birth_year, birth_country,
   login, email_address, last_review_date_sk, deleted)
SELECT r.id,
       r.customer_id,
       r.current_cdemo_sk::int,
       r.current_hdemo_sk::int,
       r.current_addr_sk::int,
       r.first_shipto_date_sk::int,
       r.first_sales_date_sk::int,
       r.salutation,
       r.first_name,
       r.last_name,
       r.preferred_cust_flag,
       r.birth_day::int,
       r.birth_month::int,
       r.birth_year::int,
       r.birth_country,
       r.login,
       r.email_address,
       r.last_review_date_sk::int,
       {{ .operation | eq "delete" }}
FROM {{ .rows }}
ON CONFLICT (id) DO UPDATE SET
  customer_id          = EXCLUDED.customer_id,
  current_cdemo_sk     = EXCLUDED.current_cdemo_sk,
  current_hdemo_sk     = EXCLUDED.current_hdemo_sk,
  current_addr_sk      = EXCLUDED.current_addr_sk,
  first_shipto_date_sk = EXCLUDED.first_shipto_date_sk,
  first_sales_date_sk  = EXCLUDED.first_sales_date_sk,
  salutation           = EXCLUDED.salutation,
  first_name           = EXCLUDED.first_name,
  last_name            = EXCLUDED.last_name,
  preferred_cust_flag  = EXCLUDED.preferred_cust_flag,
  birth_day            = EXCLUDED.birth_day,
  birth_month          = EXCLUDED.birth_month,
  birth_year           = EXCLUDED.birth_year,
  birth_country        = EXCLUDED.birth_country,
  login                = EXCLUDED.login,
  email_address        = EXCLUDED.email_address,
  last_review_date_sk  = EXCLUDED.last_review_date_sk,
  deleted              = EXCLUDED.deleted
